INSERT INTO courses VALUES ('data','Đọc hiểu dữ liệu','Toán học');
INSERT INTO content_versions(id,course_id,kind,title,state,body) VALUES
('00000000-0000-4000-8000-000000000101','data','lesson','Đọc một biểu đồ cột','published',
'{"objective":"So sánh các nhóm bằng số đếm và diễn giải chênh lệch đúng đơn vị.","reading":"Mỗi cột biểu diễn một nhóm. Đọc tên trục, đơn vị và vạch chia trước khi so sánh chiều cao. Khi trục bắt đầu ở 0, chiều cao tỉ lệ với số đếm.","example":"Thư viện lớp cho mượn 12 cuốn sách vào thứ Hai, 18 cuốn vào thứ Ba và 15 cuốn vào thứ Tư. Thứ Ba cao nhất. Chênh lệch với thứ Hai là 18 − 12 = 6 cuốn.","practice":"Nếu thứ Năm cho mượn 21 cuốn, số sách tăng bao nhiêu so với thứ Tư?","hint":"Lấy số sách thứ Năm trừ số sách thứ Tư. Kết quả là 6 cuốn."}'),
('00000000-0000-4000-8000-000000000102','data','lesson','Chọn mẫu số khi tính tỉ lệ','published',
'{"objective":"Xác định tổng thể trước khi tính phần trăm.","reading":"Tỉ lệ cho biết một phần chiếm bao nhiêu trong tổng thể. Chia số phần quan tâm cho tổng số phần rồi nhân với 100%. Hai tỉ lệ có thể khác nhau dù tử số bằng nhau.","example":"Trong 20 bạn đọc sách, 8 bạn chọn sách khoa học. Tỉ lệ là 8 ÷ 20 × 100% = 40%. Nếu khảo sát đủ 40 học sinh cả lớp thì cần biết lựa chọn của 20 bạn còn lại.","practice":"Trong 30 lượt mượn có 9 lượt mượn truyện. Tỉ lệ là bao nhiêu?","hint":"9 ÷ 30 = 0,3, tức 30%."}'),
('00000000-0000-4000-8000-000000000201','data','question','Một tuần có 14, 17 và 23 lượt đọc ở ba nhóm. Nhóm cao nhất hơn nhóm thấp nhất bao nhiêu lượt?','published','{"options":["6 lượt","9 lượt","14 lượt"],"correct":1,"explanation":"Lấy 23 trừ 14 được 9 lượt."}'),
('00000000-0000-4000-8000-000000000202','data','question','Trục đứng ghi số cuốn sách, mỗi vạch là 5 cuốn. Cột cao bốn vạch tính từ 0 biểu thị điều gì?','published','{"options":["4 học sinh","5 cuốn sách","20 cuốn sách"],"correct":2,"explanation":"Bốn khoảng, mỗi khoảng 5 cuốn, biểu thị 20 cuốn sách."}');
INSERT INTO exams(id,lesson_id,title,minutes) VALUES ('00000000-0000-4000-8000-000000000301','00000000-0000-4000-8000-000000000101','Kiểm tra đọc biểu đồ',8);
